'use strict';

const express = require('express');
const authenticate = require('../middleware/auth');
const { requirePermission } = require('../middleware/permission');
const { PERMISSIONS } = require('../config/roles');
const { getSettings, updateSettings, updateSettingsSection } = require('../controllers/settings.controller');

const router = express.Router();

// GET /api/settings — public (no auth required so the public site can load its config)
router.get('/', getSettings);

// PATCH /api/settings — partial update (ADMIN_IT only — manages all site settings)
router.patch(
  '/',
  authenticate,
  requirePermission(PERMISSIONS.SETTINGS_MANAGE),
  updateSettings
);

// PATCH /api/settings/:section — single-section update (ADMIN_IT only)
router.patch(
  '/:section',
  authenticate,
  requirePermission(PERMISSIONS.SETTINGS_MANAGE),
  updateSettingsSection
);

module.exports = router;
